import itertools

n = 28

def neg(a):
    return (-a) % n

def has_short_cycle(S, max_len=5):
    """Check if there is a cycle of length 3..max_len in Cayley graph with generators S."""
    n = 28
    S_set = set(S)
    for L in range(3, max_len+1):
        for seq in itertools.product(S, repeat=L):
            # adjacent steps must not be inverses (otherwise we'd backtrack edge)
            ok = True
            for i in range(L):
                if seq[i] == neg(seq[(i+1)%L]):
                    ok = False
                    break
            if not ok:
                continue
            # sum must be 0
            if sum(seq) % n != 0:
                continue
            # check that no proper, non-empty cyclic subsegment sums to 0
            # This ensures simple cycle (no repeated vertices)
            # For each starting position pos and length l < L, sum of seq[pos:pos+l] != 0 mod n
            has_early_zero = False
            for start in range(L):
                s = 0
                for l in range(1, L):  # length from 1 to L-1
                    idx = (start + l - 1) % L
                    s = (s + seq[idx]) % n
                    # We actually need to check cumulative sums along the walk.
                    # Better: just check all prefix sums of the cycle starting at each point.
                    # If any proper prefix sum (of the rotated sequence) is 0, it's a shorter cycle.
                    pass
            # Let's do a more systematic check:
            # Build the sequence of vertices: start at 0, add steps.
            verts = [0]
            for s in seq:
                verts.append((verts[-1] + s) % n)
            # verts[0] == verts[L] == 0.
            # Check that verts[0..L-1] are all distinct.
            if len(set(verts[:L])) == L:
                return True, seq
    return False, None

